const l = $json;
const fmt = (day) => new Date(day + 'T00:00:00Z')
  .toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
const when = l.daysOverdue === 1 ? 'yesterday' : `${l.daysOverdue} days ago`;

return { json: {
  loanId: l.loanId,
  idempotencyKey: l.idempotencyKey,
  from: setting('LENDLOOP_FROM_EMAIL', { optional: true }) || 'LendLoop <no-reply@lendloop.app>',
  to: l.borrower.email,
  subject: `Reminder: the ${l.toolName} was due back ${when}`,
  text: `Hi ${l.borrower.firstName},\n\nThe ${l.toolName} you borrowed from ${l.lenderFirstName} was due back on ${fmt(l.endDate)}. Please return it, and ask ${l.lenderFirstName} to mark it returned in LendLoop.\n\nYour requests: ${l.url}\n\n— LendLoop`,
} };

